<template>
  <section class="page-stack wide-workspace">
    <nav class="breadcrumbs" aria-label="面包屑"><RouterLink to="/therapist/patients">患者</RouterLink><span>›</span><span>{{ patient?.username||patientId }}</span><span>›</span><span>{{ tabLabel }}</span></nav>
    <header class="page-heading split"><div><span class="kicker">Patient workspace</span><h1>{{ patient?.username||'患者工作区' }}</h1><p>{{ patientId }}</p></div><StatusBadge v-if="patient" :status="patient.training_status" /></header>
    <nav class="workspace-tabs" aria-label="患者工作区"><RouterLink v-for="item in tabs" :key="item.key" :to="`/therapist/patients/${patientId}/${item.key}`">{{ item.label }}</RouterLink></nav>
    <AsyncState v-if="baseLoading" :loading="true" />
    <template v-else>
      <section v-if="tab==='overview'" class="workspace-panel"><div class="summary-strip"><div><small>评估状态</small><StatusBadge :status="patient?.assessment_status" /></div><div><small>训练状态</small><StatusBadge :status="patient?.training_status" /></div><div><small>待复核</small><strong>{{ patient?.pending_review_count??0 }}</strong></div><div><small>最近评估</small><strong>{{ formatDateTime(patient?.latest_assessment_at) }}</strong></div></div><div class="panel-grid two"><article class="surface-card"><h2>近期训练</h2><p>{{ records.length }} 条可见训练记录</p><ul class="plain-list"><li v-for="r in records.slice(0,5)" :key="r.attempt_id"><strong>{{ r.task_title }}</strong><span>{{ formatDateTime(r.created_at) }} · {{ r.analysis_status }}</span></li></ul></article><article class="surface-card"><h2>最近评估</h2><p>{{ assessments.length }} 条评估记录</p><ul class="plain-list"><li v-for="a in assessments.slice(0,5)" :key="a.id"><strong>{{ a.assessment_type }}</strong><span>{{ formatDateTime(a.assessed_at) }} · {{ a.review_status }}</span></li></ul></article></div></section>
      <section v-else-if="tab==='training'" class="workspace-panel"><h2>训练记录</h2><div class="data-table-wrap"><table class="data-table"><thead><tr><th>时间</th><th>任务</th><th>类型</th><th>分析</th><th>反馈</th></tr></thead><tbody><tr v-for="r in records" :key="r.attempt_id"><td>{{ formatDateTime(r.created_at) }}</td><td>{{ r.task_title }}</td><td>{{ r.training_type }}</td><td><StatusBadge :status="r.analysis_status" /></td><td>{{ r.feedback_summary }}</td></tr></tbody></table></div></section>
      <section v-else-if="tab==='assessment'" class="workspace-panel"><div class="section-heading"><div><h2>阶段评估</h2><p>现有评估记录及专业复核状态。</p></div><RouterLink class="secondary-button" to="/therapist/assessments">创建或复核评估</RouterLink></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>评估</th><th>来源</th><th>复核</th><th>时间</th><th>量表</th></tr></thead><tbody><tr v-for="a in assessments" :key="a.id"><td>{{ a.assessment_type }}</td><td>{{ a.evaluation_source }}</td><td><StatusBadge :status="a.review_status" /></td><td>{{ formatDateTime(a.assessed_at) }}</td><td>{{ a.instrument_name||'未提供' }} {{ a.instrument_version||'' }}</td></tr></tbody></table></div></section>
      <ClinicalStagePanel v-else-if="tab==='clinical-stage'" :patient-id="patientId" />
      <ProfilePanel v-else-if="tab==='profile'" :patient-id="patientId" />
      <PolicyPanel v-else-if="tab==='policy'" :patient-id="patientId" />
      <ControlledActionsPanel v-else-if="tab==='controlled-actions'" :patient-id="patientId" />
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'; import { useRoute } from 'vue-router'; import { therapistApi } from '@/api/therapist'; import AsyncState from '@/components/common/AsyncState.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import ClinicalStagePanel from '@/components/therapist/ClinicalStagePanel.vue'; import ControlledActionsPanel from '@/components/therapist/ControlledActionsPanel.vue'; import PolicyPanel from '@/components/therapist/PolicyPanel.vue'; import ProfilePanel from '@/components/therapist/ProfilePanel.vue'; import { formatDateTime } from '@/utils/date'; import type { AssessmentSession,TherapistPatient,TherapistTrainingRecord } from '@/types/api'
const route=useRoute(); const patientId=computed(()=>String(route.params.patientId)); const tab=computed(()=>String(route.params.tab||'overview')); const patient=ref<TherapistPatient|null>(null),records=ref<TherapistTrainingRecord[]>([]),assessments=ref<AssessmentSession[]>([]),baseLoading=ref(true); const tabs=[{key:'overview',label:'概览'},{key:'training',label:'训练'},{key:'assessment',label:'评估'},{key:'clinical-stage',label:'Clinical Stage'},{key:'profile',label:'Profile'},{key:'policy',label:'Policy'},{key:'controlled-actions',label:'Controlled Actions'}]; const tabLabel=computed(()=>tabs.find(x=>x.key===tab.value)?.label||'概览')
async function load(){baseLoading.value=true;const [patientsResult,recordsResult,assessmentsResult]=await Promise.allSettled([therapistApi.patients(),therapistApi.trainingRecords(patientId.value),therapistApi.assessmentHistory(patientId.value)]);if(patientsResult.status==='fulfilled')patient.value=patientsResult.value.find(x=>x.user_id===patientId.value)||null;if(recordsResult.status==='fulfilled')records.value=recordsResult.value;if(assessmentsResult.status==='fulfilled')assessments.value=assessmentsResult.value;baseLoading.value=false} onMounted(load);watch(patientId,load)
</script>
